import{_ as t,a,o,a6 as n}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Contact Us","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/contact-us/index.md","filePath":"api/rest-api/shop/contact-us/index.md","lastUpdated":1787290888000}'),i={name:"api/rest-api/shop/contact-us/index.md"};function s(r,e,d,h,c,u){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="contact-us" tabindex="-1">Contact Us <a class="header-anchor" href="#contact-us" aria-label="Permalink to &quot;Contact Us&quot;">​</a></h1><p>The Contact Us menu is the storefront enquiry form. It is a single endpoint, and it is <strong>public</strong> — a visitor who is not logged in can send a message.</p><h2 id="it-sends-an-email-it-does-not-store-a-record" tabindex="-1">It Sends an Email, It Does Not Store a Record <a class="header-anchor" href="#it-sends-an-email-it-does-not-store-a-record" aria-label="Permalink to &quot;It Sends an Email, It Does Not Store a Record&quot;">​</a></h2><p>This is the one thing to understand before building against it. The enquiry is emailed to the store&#39;s configured contact address; nothing addressable is created. There is no id in the response, no list endpoint, and no admin menu that shows past enquiries through the API.</p><p>So a client cannot show a customer their previous messages, cannot track whether one was answered, and cannot retry a specific submission. If your product needs any of that, keep your own copy at the point of submission — the API will not hold one for you.</p><h2 id="no-customer-token" tabindex="-1">No Customer Token <a class="header-anchor" href="#no-customer-token" aria-label="Permalink to &quot;No Customer Token&quot;">​</a></h2><p>Unlike <a href="/api/rest-api/shop/newsletter/">Newsletter</a>, sending a customer Bearer token changes nothing here: the enquiry is not linked to an account. Whoever is sending it must be identified by the <code>name</code> and <code>email</code> in the body, even for a signed-in customer — so prefill those fields from the session rather than expecting the API to infer them.</p><h2 id="what-is-required" tabindex="-1">What Is Required <a class="header-anchor" href="#what-is-required" aria-label="Permalink to &quot;What Is Required&quot;">​</a></h2><p><code>name</code>, <code>email</code>, and <code>message</code> are required; <code>contact</code> (a phone number) is optional, and an enquiry without it is accepted. Validation failures return <code>400</code> rather than the <code>422</code> used by most other write endpoints.</p><h2 id="guard-the-form-yourself" tabindex="-1">Guard the Form Yourself <a class="header-anchor" href="#guard-the-form-yourself" aria-label="Permalink to &quot;Guard the Form Yourself&quot;">​</a></h2><p>The storefront key is the only credential, and there is no uniqueness rule — the same message can be submitted repeatedly. An unprotected public form invites automated submissions, so rate limiting or a captcha is the client&#39;s responsibility.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/contact-us/submit-contact-us.html">Submit an Enquiry</a></td><td><code>POST /api/shop/contact-us</code></td><td>Send a contact-form enquiry to the store.</td></tr></tbody></table><p>The Contact Us endpoint is public — it needs the storefront key only. See <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',14)]))}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
